function pseudoChannels(requestId) {
  return FAKE_SONG_CHANNELS[requestId] ?? [
    { channel: "pulse1", track: [] },
    { channel: "pulse2", track: [] },
    { channel: "triangle", track: [] },
    { channel: "noise", track: [] }
  ];
}
function buildSongs() {
  const out = /* @__PURE__ */ new Map();
  const put = (s) => {
    if (out.has(s.requestId)) return;
    out.set(s.requestId, {
      requestId: s.requestId,
      name: s.name ?? "",
      bank: s.bank,
      cpuAddr: s.cpuAddr,
      channels: pseudoChannels(s.requestId),
      kind: s.type === "BGM" ? "bgm" : "se"
    });
  };
  for (const s of BGM_SONGS) put(s);
  for (const s of SE_SONGS) put(s);
  return out;
}
var SONGS = buildSongs();
var SONG_COUNT = BGM_SONGS.length + SE_SONGS.length;
function lookupSong(requestId) {
  return SONGS.get(requestId & 255) ?? null;
}

// src/game/prg/data/audio/audio-rom.ts
function getApePeriod(idx) {
  return FREQUENCY_TABLE[idx & 11] ?? 0;
}
function getTickDuration(idx) {
  return DURATION_TABLE[idx & 63] ?? 0;
}
function getCommandHandler(idx) {
  return COMMAND_TABLE[idx & 31] ?? 0;
}
var AudioRom = class {
  static frequency(idx) {
    return getApePeriod(idx);
  }
  static duration(idx) {
    return getTickDuration(idx);
  }
  static command(idx) {
    return getCommandHandler(idx);
  }
};

