function loadPalette(index) {
  const item = PALETTE_TABLE[index] ?? PALETTE_TABLE[0];
  const out = new Array(16);
  let src = 0;
  for (let x = 0; x < 16; x++) {
    if ((x & 3) === 0) out[x] = 15;
    else out[x] = item[src++] ?? 15;
  }
  return out;
}

