// src/game/prg/data/tables/sprite-frame-table.ts
function parseBank19Stream(stream) {
  const frames = [];
  let curSprites = [];
  let x = 0;
  let y = 0;
  let pendingTile = -1;
  let i = 0;
  const pushFrame = () => {
    if (curSprites.length > 0) {
      frames.push({ frameId: frames.length, sprites: curSprites });
    }
    curSprites = [];
    x = 0;
    y = 0;
  };
  while (i < stream.length) {
    const b = stream[i++];
    if (b >= 224) {
      pendingTile = -1;
      switch (b) {
        case 224:
          pushFrame();
          break;
        case 225: {
          const v = stream[i++] ?? 0;
          y = v & 128 ? v - 256 : v;
          break;
        }
        case 226:
          i += 3;
          break;
        case 228: {
          const v = stream[i++] ?? 0;
          x = v & 128 ? v - 256 : v;
          break;
        }
        case 229:
          i += 1;
          break;
        case 230:
          i += 1;
          break;
        case 252:
          x = 0;
          break;
        default:
          break;
      }
      continue;
    }
    if (pendingTile < 0) {
      pendingTile = b;
    } else {
      curSprites.push({ tile: pendingTile, attr: b, x, y });
      x += 8;
      pendingTile = -1;
    }
  }
  pushFrame();
  return frames;
}
