function findSkillByMoveId(moveId) {
  for (const s of SKILL_TABLE) {
    if (s.moveId === moveId) return s;
  }
  return null;
}
function findSkillsByPlayer(playerId) {
  const ids = [];
  for (const s of SKILL_TABLE) {
    if (s.players.includes(playerId)) ids.push(s.moveId);
  }
  return ids;
}

