// src/game/prg/data/scene/OpeningFrameTable.ts
var OPENING_FRAMES = [
  ...OPENING_FRAMES_SCENE_1,
  ...OPENING_FRAMES_SCENE_2,
  ...OPENING_FRAMES_SCENE_3,
  ...OPENING_FRAMES_SCENE_4,
  ...OPENING_FRAMES_SCENE_5,
  ...OPENING_FRAMES_SCENE_6,
  ...OPENING_FRAMES_SCENE_7,
  ...OPENING_FRAMES_SCENE_8,
  ...OPENING_FRAMES_SCENE_9,
  ...OPENING_FRAMES_SCENE_10,
  ...OPENING_FRAMES_SCENE_11,
  ...OPENING_FRAMES_SCENE_12
];
function getOpeningFrame(nesFrame) {
  const idx = nesFrame - 10;
  return idx >= 0 && idx < OPENING_FRAMES.length ? OPENING_FRAMES[idx] : void 0;
}

// src/game/prg/code/scene/SceneController.ts
var SceneController = class {
  constructor(store, input) {
    this.store = store;
    this.input = input;
    /** bank00 6-slot timer dispatcher（PRG $9EEF/$9FA8 翻译）；由 Tsubasa2 boot() 注入 */
    this.scheduler = null;
    /**
     * 帧级 pending callbacks（scheduler 残留 IDLE 兜底）— scheduleAfter 推入此 list,
     * BootRouter.update 每帧调 _tickPending 推进 timer 到 0 时 invoke cb.
     * V0.6 修 scheduler 不稳定时 Scene14.Scene15 永远 not ready.
     */
    this._pendingCallbacks = [];
  }
  /** BootRouter.update 每帧调一次 — 推进 pending callbacks 并 invoke 到期的 */
  _tickPending() {
    if (this._pendingCallbacks.length === 0) return;
    const remain = [];
    for (const p of this._pendingCallbacks) {
      if (p.framesLeft <= 0) {
        try {
          p.cb();
        } catch (e) {
        }
      } else {
        p.framesLeft--;
        if (p.framesLeft <= 0) {
          try {
            p.cb();
          } catch (e) {
            void e;
          }
        } else {
          remain.push(p);
        }
      }
    }
    this._pendingCallbacks.length = 0;
    for (const p of remain) this._pendingCallbacks.push(p);
  }
  /**
   * 注入 bank00 scheduler（PRG $9FA8 pushState 翻译）。
   * 由 Tsubasa2 boot() 在 BootRouter 构造之后批量调用；
   * 注入后子类可用 `scheduleAfter(timer, cb)` 替代手写的 `this.counter--` 模式。
   */
  attachScheduler(scheduler) {
    this.scheduler = scheduler;
  }
  /**
   * 等 timer 帧后调 callback（PRG $9FA8 pushState + LDA #$XX 翻译）。
   *
   * 行为对照：
   *   ROM: LDA #$XX / JSR $9FA8 — 入栈 timer + JMP $9EFB scheduler tail
   *        → 每帧 DEC timer → timer=0 自动 dispatchTail
   *   H5:  pushState({timer, callback}) → InterruptService.nmi() tickDispatch() callback
   *
   * Fallback：
   *   scheduler 未注入 → callback 立即同步执行（保证子类语义不丢）
   *
   * @param timer 等待帧数
   * @param callback timer→0 时同步派发
   * @returns slot id（0-5，失败 -1）
   */
  scheduleAfter(timer, callback) {
    const t = timer & 255;
    if (t === 0) {
      try {
        callback();
      } catch (e) {
        void e;
      }
      return -1;
    }
    this._pendingCallbacks.push({ framesLeft: t, cb: callback });
    void this.scheduler;
    return this._pendingCallbacks.length - 1;
  }
  /** 每帧渲染（写入渲染缓冲/调色板） */
  onRender() {
  }
  /**
   * ⚠️ slot 触发钩子 (PRG $C5xx slot handler entry 翻译) — v2 stub
   *
   * 与 onUpdate 的区别:
   *   - onUpdate 每帧调 (BootRouter.update() 在 game loop 末尾)
   *   - **onSlotTick 仅在 Bank00MainLoopService slot 触发时调** (典型: 每 12 帧 1 次)
   *
   * ROM 模型 (BANK02_ANALYSIS.md §6):
   *   - 6-slot dispatcher 每 NMI frame 调所有 slot counter
   *   - slot counter→0 → 调对应 handler entry (`JSR $A000` / `JSR $A160`)
   *   - handler 跑 RTS → 自动回到 dispatcher
   *   - 不是每帧都跑 — 是周期触发
   *
   * H5 默认空实现, scene 不需要 slot 驱动时可忽略.
   * 真正需要 slot 触发的 scene (Scene0 当前思考可能需要的) 覆盖此方法.
   *
   * @param tickCount slot 触发序号 (0=首触发, 1+=周期内第 N 次)
   */
  onSlotTick(_slotIdx, _tickCount) {
  }
};

// src/game/prg/code/system/InputService.ts
var InputService = class {
  constructor(store) {
    this.store = store;
    /** 外部注入的控制器状态（P1/P2，与 core/controller 一致：state[] 每键 0x40=松开/0x41=按下） */
    this.rawState = [
      [64, 64, 64, 64, 64, 64, 64, 64],
      [64, 64, 64, 64, 64, 64, 64, 64]
    ];
  }
  /** 每帧由外层注入手柄状态（core Controller.state） */
  setControllerState(controllerId, state) {
    this.rawState[controllerId - 1] = state;
  }
  /**
   * 读取两控制器 → 更新 ram_001C/001D（当前）/ ram_001E/001F（按下沿）
   * 按下沿 = 当前 & ~上一帧
   */
  readControllers() {
    const store = this.store;
    for (let x = 2; x >= 1; x--) {
      const idx = x - 1;
      const state = this.rawState[idx];
      let cur = 0;
      for (let i = 0; i < 8; i++) {
        if (state[i] === 65) cur |= 1 << i;
      }
      const prev = store.readByte(26 + x);
      store.writeByte(27 + x, cur);
      store.writeByte(29 + x, cur & ~prev);
    }
  }
  /** 语义化查询：控制器 n（1/2）某键是否按下 */
  isDown(controller, button) {
    return (this.store.readByte(controller === 1 ? 28 : 29) & button) !== 0;
  }
  /** 语义化查询：控制器 n 某键本帧按下沿 */
  isPressed(controller, button) {
    return (this.store.readByte(controller === 1 ? 30 : 31) & button) !== 0;
  }
};

