// src/game/prg/code/scene/OpeningSceneController.ts
var OPENING_END_NES_FRAME = 4201;
var H5_FRAME_OFFSET = 10;
var STORY_CUP_SCREEN_INDEX = 11;
var OpeningSceneController = class extends SceneController {
  constructor(store, input) {
    super(store, input);
    this.sceneId = OPENING_SCENE_ID;
    this.audio = null;
    /** H5 内部片头帧计数器（onUpdate 自增；每帧 +1）。 */
    this.h5Frame = 0;
    /** 当前帧 GT 数据 */
    this.currentFrame = null;
    /** 当前帧 CHR per-scanline 计划 */
    this.currentChrPlan = [];
    /** 待写入 ppu.nameTable 的 NT tile 变化行 */
    this.ntQueue = [];
    /** 待写入 ppu.nameTable 的属性表变化行 */
    this.attrQueue = [];
    /** 当前帧 GT scroll 寄存器(供 applyNtToPpu 写入 PPU) */
    this.currentScroll = { v: 0, h: 0, vt: 0, ht: 0, fv: 0, fh: 0, cv: 0, ch: 0, cvt: 0, cht: 0 };
    /**
     * START 跳过标志(进 TitleMenuScene 后此 flag 不再生效,跳走由 BootRouter 控制)。
     * 保留仅供 OpeningScene 内连续双帧 START 防御性 short-circuit。
     */
    this.skipped = false;
    this._applyNtLogged = false;
  }
  attachAudio(audio) {
    this.audio = audio;
  }
  onEnter() {
    this.resetSceneState();
    this.applyEnterRenderState();
    if (this.audio) {
      this.audio.playBgm(1);
    }
  }
  /**
   * 重置片头逐帧状态(h5Frame 归零 + 帧缓冲清空)。
   * onEnter 与 resetForLoop(循环重播)共用。
   */
  resetSceneState() {
    this.h5Frame = 0;
    this.currentFrame = null;
    this.currentChrPlan = [];
    this.ntQueue = [];
    this.attrQueue = [];
    this.currentScroll = { v: 0, h: 0, vt: 0, ht: 0, fv: 0, fh: 0, cv: 0, ch: 0, cvt: 0, cht: 0 };
  }
  /**
   * 一次性渲染状态:PPU CTRL/MASK / fade 满亮 / scrollFlag / 禁用中间 CHR 切换 /
   * 清 nametable + 隐藏 OAM。
   *
   * 第一遍由 BootRouter.changeScene 清 nametable/OAM 后调 onEnter;
   * **循环重播不经过 changeScene**,必须在这里重铺,否则上一轮 title 屏残留的
   * fade=0(黑屏)/ctrl 被改/nametable 残留 title 内容/精灵残留 会让 tecmo logo 消失。
   */
  applyEnterRenderState() {
    this.store.fade.bg = 15;
    this.store.fade.spr = 15;
    this.store.ppuState.ctrl = 136;
    this.store.ppuState.mask = 30;
    this.store.scene.scrollX = 0;
    this.store.scene.scrollY = 1;
    this.store.scene.scrollFlag = 128;
    this.store.writeByte(117, 0);
    this.store.writeByte(118, 0);
    this.store.writeByte(94, 0);
    this.store.writeByte(95, 0);
    this.store.writeByte(156, 0);
    this.store.writeByte(157, 0);
    this.store.writeByte(158, 0);
    this.store.writeByte(159, 0);
    this.store.writeByte(160, 0);
    this.store.writeByte(161, 0);
    for (let addr = 8192; addr <= 12287; addr++) this.store.writeByte(addr, 0);
    for (let i = 512; i < 768; i++) this.store.writeByte(i, 248);
    this.store.oam.shadowOam.fill(248);
  }
  /** H5 帧 -> NES 绝对帧(GT 时间线基准) */
  nesFrameOf() {
    return this.h5Frame + H5_FRAME_OFFSET;
  }
  onUpdate(_frame) {
    if (this.skipped) return void 0;
    if (this.input.isPressed(1, 8 /* Start */)) {
      this.skipped = true;
      return TITLE_MENU_SCENE_ID;
    }
    const nesFrame = this.nesFrameOf();
    this.h5Frame++;
    if (this.h5Frame >= OPENING_END_NES_FRAME - H5_FRAME_OFFSET) {
      this.resetForLoop();
      return void 0;
    }
    const fr = getOpeningFrame(nesFrame);
    if (!fr) return void 0;
    this.applyFrameData(fr);
    return void 0;
  }
  /**
   * 重置 opening 内部状态以便从 f10 重新播(用户未按 START 走 loop)。
   * 循环重播 = 重新进入 OpeningScene:除 skipped 标志(用户 START 后永远不进
   * opening)之外,逐帧状态 + 一次性渲染状态 + BGM 必须完整重铺。
   * 不重置 skipped 标志 — 用户 START 后永远不进 opening。
   */
  resetForLoop() {
    this.resetSceneState();
    this.applyEnterRenderState();
    if (this.audio) {
      this.audio.playBgm(1);
    }
  }
  /** 把单帧 GT 数据(palette/OAM/CHR plan/NT/attr/scroll)应用到 store + 控制器内部缓冲 */
  applyFrameData(fr) {
    this.currentFrame = fr;
    if (fr.p) {
      this.store.palette.loadBg(fr.p.bg);
      this.store.palette.loadSpr(fr.p.spr);
    }
    this.applyOamDiff(fr.o);
    this.currentChrPlan = fr.c;
    this.ntQueue = fr.n.slice();
    this.attrQueue = fr.a.slice();
    this.currentScroll = fr.s;
  }
  /** 供 Tsubasa2.frame 取本帧 CHR per-scanline 计划 */
  getChrPlan() {
    return this.currentChrPlan;
  }
  /**
   * 在 InterruptService.renderCommit 之后、PPU 渲染之前调用。
   * 直接把本帧 NT/属性表 diff 写入 ppu.nameTable,并写入 GT scroll 寄存器,
   * 让 PPU renderBgScanline 按 cntV/cntH 选择正确的 nametable。
   */
  applyNtToPpu(ppu2) {
    if (!ppu2 || !ppu2.nameTable) return;
    try {
      this._applyNtToPpuImpl(ppu2);
    } catch (e) {
      if (!this._applyNtLogged) {
        console.warn("[OpeningScene.applyNtToPpu] \u5185\u90E8\u5F02\u5E38\u5DF2 catch, \u540E\u7EED\u5E27\u7EE7\u7EED. err=", e.message);
        this._applyNtLogged = true;
      }
    }
  }
  /** applyNtToPpu 真实实现 (V0.7+ try/catch 包裹) */
  _applyNtToPpuImpl(ppu2) {
    const s = this.currentScroll;
    ppu2.regV = s.v & 1;
    ppu2.regH = s.h & 1;
    ppu2.regVT = s.vt & 31;
    ppu2.regHT = s.ht & 31;
    ppu2.regFV = s.fv & 7;
    ppu2.regFH = s.fh & 7;
    ppu2.renderStartOverride = {
      cntFV: s.fv & 7,
      cntV: s.v & 1,
      cntH: s.h & 1,
      cntVT: s.vt & 31,
      cntHT: s.ht & 31
    };
    const fr = this.currentFrame;
    ppu2.scrollScanOverrides = fr && fr.sc && fr.sc.length ? fr.sc.map((o) => ({ s: o.s, h: o.h & 1, ht: o.ht & 31, fh: o.fh & 7 })) : null;
    for (const row of this.ntQueue) {
      const nt = ppu2.nameTable[row.ni];
      if (!nt || !nt.tile) continue;
      const base = row.r * 32;
      for (let c = 0; c < 32; c++) {
        nt.tile[base + c] = row.d[c] & 255;
      }
    }
    for (const row of this.attrQueue) {
      const nt = ppu2.nameTable[row.ni];
      if (!nt || !nt.attrib) continue;
      this.applyAttrRow(nt, row.r, row.d);
    }
    this.ntQueue = [];
    this.attrQueue = [];
  }
  /** 标准 64 字节属性表行 -> 960 项逐 tile attrib(PPU 期望 palette group 偏移 0/4/8/12) */
  applyAttrRow(nt, ar, row8) {
    for (let ac = 0; ac < 8; ac++) {
      const v = row8[ac] & 255;
      const baseY = ar * 4;
      const baseX = ac * 4;
      if (nt.tile) nt.tile[960 + ar * 8 + ac] = v;
      for (let dy = 0; dy < 4; dy++) {
        for (let dx = 0; dx < 4; dx++) {
          const group = dy & 2 | (dx & 2) >> 1;
          const pal = v >> group * 2 & 3;
          const ty = baseY + dy;
          const tx = baseX + dx;
          if (ty < 32 && tx < 32) {
            nt.attrib[ty * 32 + tx] = pal << 2;
          }
        }
      }
    }
  }
  /** 应用 OAM diff 到 shadowOam */
  applyOamDiff(diff) {
    const shadow = this.store.oam.shadowOam;
    for (const entry of diff) {
      const idx = entry[0] ?? 0;
      if (idx < 0 || idx >= 64) continue;
      const base = idx * 4;
      shadow[base + 0] = (entry[1] ?? 248) & 255;
      shadow[base + 1] = (entry[2] ?? 0) & 255;
      shadow[base + 2] = (entry[3] ?? 0) & 255;
      shadow[base + 3] = (entry[4] ?? 0) & 255;
    }
  }
  /**
   * 供 Scene0Controller 承接 story_cup 精灵(f3600 切场景时 changeScene 清 OAM,
   * Scene0 Drift30 需要 story_cup 的 64 sprite 下漂)。
   */
  static loadStoryCupOam(store) {
    const screen = OPENING_SCREENS[STORY_CUP_SCREEN_INDEX];
    if (!screen) return;
    const oam = screen.mid.oam;
    const shadow = store.oam.shadowOam;
    for (let i = 0; i < 64 && i < oam.length; i++) {
      const o = oam[i];
      const base = i * 4;
      shadow[base + 0] = (o[0] ?? 248) & 255;
      shadow[base + 1] = (o[1] ?? 0) & 255;
      shadow[base + 2] = (o[2] ?? 0) & 255;
      shadow[base + 3] = (o[3] ?? 0) & 255;
    }
  }
  /** 供 Scene0Controller 读取 story_cup 的 mid palette(BG 渐隐底色) */
  static storyCupPalette() {
    const screen = OPENING_SCREENS[STORY_CUP_SCREEN_INDEX];
    return screen ? screen.mid.pal : null;
  }
};

