// src/game/prg/code/scene/TitleMenuSceneController.ts
var TITLE_MENU_SCREEN_INDEX = 12;
var TITLE_MENU_ITEMS_Y = [
  108,
  // kickoff — 文字区 Y=92..124 中间
  156
  // continue — 文字区 Y=132..156 中间
];
var TitleMenuSceneController = class extends SceneController {
  constructor(store, input) {
    super(store, input);
    this.sceneId = TITLE_MENU_SCENE_ID;
    /** 当前 CHR per-scanline plan (整屏 title CHR banks) */
    this.currentChrPlan = [];
    /** 缓存 title screen 数据让 applyNtToPpu 引用 */
    this.cachedScreen = null;
    this.paletteInitSvc = new TitleMenuPaletteInitService(store);
    this.cursorSvc = new TitleMenuCursorService(store, input, TITLE_MENU_ITEMS_Y.length - 1);
  }
  onEnter() {
    const store = this.store;
    const screen = OPENING_SCREENS[TITLE_MENU_SCREEN_INDEX];
    if (!screen) return;
    const mid = screen.mid;
    this.paletteInitSvc.initState();
    this.cursorSvc.reset();
    this.cursorSvc.setSpritePos(TITLE_MENU_ITEMS_Y[0], 88);
    this.cursorSvc.tickPerFrame(TITLE_MENU_ITEMS_Y);
    store.palette.loadBg(mid.pal.bg);
    store.palette.loadSpr(mid.pal.spr);
    this.applyOamFull(mid.oam);
    for (let ni = 0; ni < mid.nt.length && ni < 4; ni++) {
      const n = mid.nt[ni];
      const nametableBase = 8192 + ni * 1024;
      for (let i = 0; i < 1024 && i < n.tile.length; i++) {
        store.writeByte(nametableBase + i, n.tile[i] & 255);
      }
      const attribBase = nametableBase + 960;
      for (let i = 0; i < 1024 && i < n.attrib.length; i++) {
        store.writeByte(attribBase + i, n.attrib[i] & 255);
      }
    }
    this.currentChrPlan = [{ s: 0, b: TITLE_SCREEN_CHR_BANKS.slice() }];
    store.ppuState.ctrl = 136;
    store.ppuState.mask = 30;
    store.fade.bg = 15;
    store.fade.spr = 15;
    store.scene.scrollX = 0;
    store.scene.scrollY = 0;
    store.scene.scrollFlag = 128;
    this.cachedScreen = screen;
  }
  /**
   * 每帧:
   * 1. cursor service tick (Up/Down 沿检测 + sprite paint 进 shadowOam)
   * 2. A 键按下 → 按当前 cursorIdx 切到目标 sceneId。
   *
   * 目标 sceneId 选择（最小可验证）：
   *   idx=0 KICKOFF  → SCENE_14_ID (loadSceneRows + 调色板 + 精灵装载, 主游戏 prep)
   *   idx=1 CONTINUE → SCENE_14_ID (TODO: 与 KICKOFF 区分)
   *
   * ⚠️ 当前不启动 bank00 5-mode dispatcher（booted=false）— Scene14 跑完 return 2 →
   *    Scene2 hub (do-nothing) → 卡住。这证明 Scene14 controller 路径可跑通, 后续完整流程
   *    需要修 dispatcher boot。
   */
  onUpdate(_frame) {
    this.cursorSvc.tickPerFrame(TITLE_MENU_ITEMS_Y);
    if (this.input.isPressed(1, 1 /* A */)) {
      const idx = this.cursorSvc.getIdx();
      return SCENE_14_ID;
    }
    return void 0;
  }
  /** 供 Tsubasa2.frame 取本场景 CHR per-scanline plan */
  getChrPlan() {
    return this.currentChrPlan;
  }
  /**
   * 强制推 NT 字节到 PPU（每帧 frame() 调）
   * 真实 ROM 行为：title 是稳定画面,每帧 VBlank 不重写 NT,这里 NT 已经在 onEnter
   *   写到 store (writeByte 0x2000+0x3C0),由 store.setVramTarget(target.ppu) 自动 flush。
   *   但 page Tsubasa2.frame() 中 setVramTarget 时机在 nmi 之前 — 当 TitleMenu 进入时
   *   可能 vramTarget 还是 null。本方法直接 push 到 PPU (覆盖任何残留)。
   */
  applyNtToPpu(ppu2) {
    if (!ppu2 || !this.cachedScreen) return;
    if (Array.isArray(ppu2.nameTable) && ppu2.nameTable.length >= 1) {
      const nt0Tiles = this.cachedScreen.mid.nt[0]?.tile;
      const nt0Att = this.cachedScreen.mid.nt[0]?.attrib;
      if (nt0Tiles && nt0Tiles.length >= 32 * 30) {
        const writeOne = (target, tiles, attrs) => {
          for (let i = 0; i < 32 * 30 && i < tiles.length; i++) {
            target[i] = tiles[i] & 255;
          }
          for (let i = 0; i < 64 && i < attrs.length; i++) {
            const addr = 960 + i;
            target[addr] = attrs[i] & 255;
          }
        };
        writeOne(ppu2.nameTable[0], nt0Tiles, nt0Att);
        if (ppu2.nameTable[1]) writeOne(ppu2.nameTable[1], this.cachedScreen.mid.nt[1]?.tile ?? [], this.cachedScreen.mid.nt[1]?.attrib ?? []);
        if (ppu2.nameTable[2]) writeOne(ppu2.nameTable[2], this.cachedScreen.mid.nt[2]?.tile ?? [], this.cachedScreen.mid.nt[2]?.attrib ?? []);
        if (ppu2.nameTable[3]) writeOne(ppu2.nameTable[3], this.cachedScreen.mid.nt[3]?.tile ?? [], this.cachedScreen.mid.nt[3]?.attrib ?? []);
      }
    }
    if ("regV" in ppu2) ppu2.regV = 0;
    if ("regH" in ppu2) ppu2.regH = 0;
    if ("regVT" in ppu2) ppu2.regVT = 0;
    if ("regHT" in ppu2) ppu2.regHT = 0;
    if ("regFV" in ppu2) ppu2.regFV = 0;
    if ("regFH" in ppu2) ppu2.regFH = 0;
    if ("mask" in ppu2) ppu2.mask = 30;
    if ("ctrl" in ppu2) ppu2.ctrl = 136;
  }
  /** 应用 OAM 全量 (4-tuple [Y, tile, attr, X])到 shadowOam */
  applyOamFull(oam) {
    const shadow = this.store.oam.shadowOam;
    for (let i = 0; i < 64 && i < oam.length; i++) {
      const o = oam[i];
      const base = i * 4;
      shadow[base + 0] = (o[0] ?? 248) & 255;
      shadow[base + 1] = (o[1] ?? 0) & 255;
      shadow[base + 2] = (o[2] ?? 0) & 255;
      shadow[base + 3] = (o[3] ?? 0) & 255;
    }
    for (let i = oam.length; i < 64; i++) {
      const base = i * 4;
      shadow[base + 0] = 248;
      shadow[base + 1] = 248;
      shadow[base + 2] = 248;
      shadow[base + 3] = 248;
    }
  }
};

// src/game/prg/code/scene/MeetingSceneController.ts
var FIRST_MEETING_SCRIPT_ID = 0;
var MeetingSceneController = class extends SceneController {
  constructor() {
    super(...arguments);
    this.sceneId = MEETING_SCENE_ID;
    this.scriptEngine = null;
    this.scriptCtx = null;
  }
  /** Tsubasa2 构造时注入（跟 OpeningScene.attachAudio 同模式） */
  attachScriptEngine(engine) {
    this.scriptEngine = engine;
  }
  onEnter() {
    this.store.writeByte(1, MEETING_SCENE_ID & 255);
    this.store.ppuState.ctrl = 40;
    this.store.writeByte(1511, 0);
    if (this.scriptEngine) {
      this.scriptCtx = this.scriptEngine.start(FIRST_MEETING_SCRIPT_ID);
      const seg = this.scriptCtx;
      if (seg && seg.bytes.length > 0) {
        const head = Array.from(seg.bytes.slice(0, 32)).map((b) => b.toString(16).padStart(2, "0")).join(" ");
        const scriptsTotalBytes = seg.bytes.length;
        const opCount0x01 = Array.from(seg.bytes).filter((b) => b === 1).length;
        const opCount0x0d = Array.from(seg.bytes).filter((b) => b === 13).length;
        console.log(
          `[Meeting] scriptId=0x${FIRST_MEETING_SCRIPT_ID.toString(16)} bytes=${scriptsTotalBytes} 0x01=${opCount0x01} 0x0d=${opCount0x0d} head=[${head}]`
        );
      }
    } else {
      this.scriptCtx = null;
    }
  }
  onUpdate(_frame) {
    if (!this.scriptEngine || !this.scriptCtx) {
      return void 0;
    }
    const stillRunning = this.scriptEngine.step(this.scriptCtx);
    if (!stillRunning && !this.scriptCtx.waitingInput) {
      return 1024;
    }
    return void 0;
  }
};

// src/game/prg/code/scene/MatchStartSceneController.ts
var MatchStartSceneController = class extends SceneController {
  constructor() {
    super(...arguments);
    this.sceneId = MATCH_START_SCENE_ID;
    this.matchEngine = null;
    this.matchHud = null;
    this.matchTurn = null;
    /** false = 等 START; true = 比赛已启动（stay 在比赛页面） */
    this.matchStarted = false;
  }
  /** Tsubasa2 入口注入 MatchEngineService */
  attachMatchEngine(engine) {
    this.matchEngine = engine;
  }
  /** Tsubasa2 入口注入 MatchHudService（HUD 时间/比分渲染） */
  attachMatchHud(hud) {
    this.matchHud = hud;
  }
  /** Tsubasa2 入口注入 MatchTurnService（回合决策） */
  attachMatchTurn(turn) {
    this.matchTurn = turn;
  }
  onEnter() {
    this.store.writeByte(1, MATCH_START_SCENE_ID & 255);
    this.matchStarted = false;
  }
  onUpdate(_frame) {
    if (this.matchStarted) {
      this.matchEngine?.update(_frame);
      this.matchTurn?.advanceTurn();
      this.matchHud?.refresh();
      return void 0;
    }
    if (this.matchEngine && this.input.isPressed(1, 1 /* A */)) {
      const home = this.store.readByte(1576) || 2;
      const away = 1;
      this.matchEngine.startMatch(home, away);
      this.matchStarted = true;
    }
    return void 0;
  }
};

