// src/game/prg/code/match/MatchEngineService.ts
var MatchEngineService = class {
  constructor(store) {
    this.store = store;
  }
  /**
   * 开始比赛：初始化双方球队、比分、时间、控球方。
   */
  startMatch(homeTeam, awayTeam) {
    this.store.write("ram_044E", 0);
    this.store.write("ram_0621", 0);
    this.store.write("ram_0617", 0);
    const config = getMatchConfig(homeTeam, awayTeam);
    return {
      homeTeam,
      awayTeam,
      homeScore: 0,
      awayScore: 0,
      timeMinutes: config.durationMinutes,
      timeSeconds: 0,
      possession: 0,
      currentPlayerIdx: 0
    };
  }
  /**
   * 装载球员槽位：写入球员数 + 逐项 [playerId, type, state]。
   */
  loadPlayerSlots(playerIds) {
    this.store.write("ram_0600", playerIds.length);
    for (let i = 0; i < playerIds.length; i++) {
      this.store.write(`ram_0601_${i}`, playerIds[i]);
      this.store.write(`ram_0606_${i}`, 0);
      this.store.write(`ram_060B_${i}`, 0);
    }
    this.store.write("ram_0617", playerIds.length);
  }
  /**
   * 读取球员槽位：[playerId, type, state]。
   */
  getPlayerSlot(idx) {
    return {
      slotIdx: idx,
      playerId: this.store.read(`ram_0601_${idx}`),
      type: this.store.read(`ram_0606_${idx}`),
      state: this.store.read(`ram_060B_${idx}`)
    };
  }
  /**
   * 球员数据装载：槽位 → 帧工作区（state/type/playerId）。
   */
  loadPlayerData(idx) {
    const slot = this.getPlayerSlot(idx);
    this.store.write("ram_043D", slot.state);
    this.store.write("ram_043E", slot.type);
    this.store.write("ram_0442", slot.playerId);
  }
  /**
   * 球员交换：两个槽位内容互换；type=1, state=0 标记为新槽。
   */
  swapPlayers(idxX, idxY) {
    const slotX = this.getPlayerSlot(idxX);
    const slotY = this.getPlayerSlot(idxY);
    this.store.write(`ram_0601_${idxX}`, slotY.playerId);
    this.store.write(`ram_060B_${idxX}`, slotY.state);
    this.store.write(`ram_0606_${idxX}`, slotY.type);
    this.store.write(`ram_0606_${idxY}`, 1);
    this.store.write(`ram_060B_${idxY}`, 0);
    this.store.write(`ram_0601_${idxY}`, slotX.playerId);
  }
  /**
   * 每帧比赛逻辑：
   * - 球员遍历循环：递增索引 → 与总数比较 → 未到尾部继续
   * - 帧尾例程：HUD 更新 / 时间推进
   * - 控球方判定 → 分发
   */
  update(frame) {
    void frame;
    const store = this.store;
    const totalPlayers = store.read("ram_0600");
    let currentIdx = store.read("ram_0616");
    currentIdx = currentIdx + 1 & 255;
    store.write("ram_0616", currentIdx);
    if (currentIdx !== totalPlayers) {
      return;
    }
    this.frameTailUpdate();
    const possession = store.read("ram_043B");
    this.dispatchPossession(possession);
  }
  /**
   * 帧尾更新：比赛时间递减；分钟/秒计满后半场/终场判定。
   */
  frameTailUpdate() {
    const store = this.store;
    const seconds = store.read("ram_0469");
    if (seconds > 0) {
      store.write("ram_0469", seconds - 1);
    } else {
      const minutes = store.read("ram_0468");
      if (minutes > 0) {
        store.write("ram_0468", minutes - 1);
        store.write("ram_0469", 59);
      }
    }
  }
  /**
   * 控球方分发（5 种状态机）：
   * - 0: 继续主循环
   * - 1: 设置 ram_0612=$0A → 防守例程
   * - 2: 重置栈指针
   * - 3: 防守例程 → 重置栈
   * - 4: ram_0617=0 → 跳回主循环
   */
  dispatchPossession(possession) {
    const store = this.store;
    switch (possession) {
      case 0:
        break;
      case 1:
        store.write("ram_0612", 10);
        this.defenseRoutine();
        break;
      case 2:
        break;
      case 3:
        this.defenseRoutine();
        break;
      case 4:
        store.write("ram_0617", 0);
        break;
      default:
        break;
    }
  }
  /**
   * 防守例程：
   * - ram_0617 bit7 置位 → 跳过
   * - 控球方=2 → 跳过
   * - ram_062D=0；ram_044E = ram_0444 & 3；ram_0617 |= 0x80
   */
  defenseRoutine() {
    const store = this.store;
    const flags = store.read("ram_0617");
    if ((flags & 128) !== 0) return;
    const possession = store.read("ram_043B");
    if (possession === 2) return;
    store.write("ram_062D", 0);
    const playerFlags = store.read("ram_0444");
    store.write("ram_044E", playerFlags & 3);
    store.write("ram_0617", flags | 128);
  }
  /** 球员槽位递增：当前球员索引 +1 */
  advancePlayerSlot() {
    const idx = this.store.read("ram_0616") + 1 & 255;
    this.store.write("ram_0616", idx);
    return idx;
  }
  /** 检查球员遍历完成：当前索引 == 球员总数 */
  isPlayerTraversalComplete() {
    return this.store.read("ram_0616") === this.store.read("ram_0600");
  }
  /** 导出配置供外部访问 */
  get config() {
    return DEFAULT_MATCH_CONFIG;
  }
};

// src/game/prg/code/match/MatchTurnService.ts
var MatchTurnService = class {
  constructor(store) {
    this.store = store;
  }
  /**
   * 推进一个回合（传球/带球/射门/铲球，V0.5 实现）
   *
   * 对应 asm $8000-$800A 三路跳转表，主调用方（MatchEngineService）按当前
   * 控球方 / 比赛阶段分派到不同入口：
   *   - 球权方 0..3 → $8083（常规回合决策）
   *   - 球权方 = 守门员方 → $84A1（守门员回合）
   *   - 死球 → $814C（死球回合）
   *
   * 当前 stub：保留调用契约 + 说明 bank11 引用，行为由 MatchEngineService
   * update() 在每帧调用。
   */
  advanceTurn() {
    void this.store;
  }
  /**
   * 当前回合类型查询（读 ram_003B bit 模式）。
   */
  getCurrentTurnType() {
    const v = this.store.readByte(59) & 255;
    if (v < 0 || v > 7) return 2 /* DeadBall */;
    return v;
  }
  /**
   * 回合计数查询（ram_05D4/ram_05D8）：用于检测重复回合/死循环。
   */
  getTurnMarker() {
    const cur = this.store.readByte(1492) & 255;
    const last = this.store.readByte(1496) & 255;
    return cur << 8 | last;
  }
};

// src/game/prg/code/match/MatchAuxService.ts
var MatchAuxService = class {
  constructor(store) {
    this.store = store;
  }
  /**
   * 处理死球/界外事件（V0.5 实现）
   *
   * 对应 asm $814C 死球回合入口：检测球坐标 → 越界 → 写重启类型
   * → 通知 MatchTurnService 重启回合（间接通过更新 ram_003B）。
   */
  handleDeadBall() {
    const ballX = this.store.readByte(1072);
    const ballY = this.store.readByte(1073);
    const restart = this.detectRestart(ballX, ballY);
    if (restart !== 0 /* None */) {
      this.store.writeByte(59, restart & 255);
    }
  }
  /**
   * 越界检测：球 X 越界 → 角球或球门球；球 Y 越界 → 界外球
   * - X ≤ 0 或 X ≥ 250 → X 越界（角球/球门球）
   * - Y ≤ 0 或 Y ≥ 230 → Y 越界（界外）
   *
   * 控球方（ram_043B）决定是角球还是球门球：
   * - 进攻方碰出底线 → 角球
   * - 防守方碰出底线 → 球门球
   */
  detectRestart(ballX, ballY) {
    if (ballX <= 1 || ballX >= 254) {
      const possession = this.store.readByte(1083) & 255;
      return possession === 0 ? 3 /* GoalKick */ : 2 /* CornerKick */;
    }
    if (ballY <= 1 || ballY >= 238) {
      return 1 /* ThrowIn */;
    }
    return 0 /* None */;
  }
  /**
   * 换人操作（按战术配置）。
   * 当前 stub：将换人标志置位，真实逻辑由 MatchEventService 接管。
   *
   * @param playerIdx  换上球员 idx
   * @param slot       被换下球员 slot
   */
  handleSubstitution(playerIdx, slot) {
    this.store.writeByte(1554, (this.store.readByte(1554) | 128) & 255);
    void playerIdx;
    void slot;
  }
  /**
   * 查询球是否在界内。
   */
  isBallInBounds() {
    return this.detectRestart(
      this.store.readByte(1072),
      this.store.readByte(1073)
    ) === 0 /* None */;
  }
  /**
   * 球坐标查询。
   */
  getBallXY() {
    return {
      x: this.store.readByte(1072) & 255,
      y: this.store.readByte(1073) & 255
    };
  }
};

// src/game/prg/code/match/MatchHudService.ts
var MatchHudService = class {
  constructor(store) {
    this.store = store;
  }
  /**
   * 刷新 HUD 到渲染缓冲（每帧调用）
   *
   * 行为：
   * 1. 读 ram_0468/0469 → 时间
   * 2. 读 ram_044E/0450 → 比分
   * 3. 转换为 BCD 字符（'0'-'9' tile 索引 16-25）
   * 4. 写入 OAM HUD 字符区（$0200 起 12 字节 = 4 字符 × 3 字节）
   *
   * NMI 渲染时通过 $04 字符队列同步刷出。
   */
  refresh() {
    const minutes = this.store.readByte(1128) & 255;
    const seconds = this.store.readByte(1129) & 255;
    const homeScore = this.store.readByte(1102) & 255;
    const awayScore = this.store.readByte(1104) & 255;
    const minHi = Math.floor(minutes / 10);
    const minLo = minutes % 10;
    const secHi = Math.floor(seconds / 10);
    const secLo = seconds % 10;
    const homeHi = Math.floor(homeScore / 10);
    const homeLo = homeScore % 10;
    const awayHi = Math.floor(awayScore / 10);
    const awayLo = awayScore % 10;
    const hudY = 8;
    const tiles = [
      this.toTileDigit(homeHi),
      this.toTileDigit(homeLo),
      this.toTileDigit(minHi),
      this.toTileDigit(minLo),
      this.toTileDigit(secHi),
      this.toTileDigit(secLo),
      this.toTileDigit(awayHi),
      this.toTileDigit(awayLo)
    ];
    for (let i = 0; i < 8; i++) {
      const base = 512 + i * 4;
      this.store.writeByte(base, hudY);
      this.store.writeByte(base + 1, tiles[i]);
      this.store.writeByte(base + 2, 2);
      this.store.writeByte(base + 3, 32 + i * 12);
    }
    this.store.writeByte(1301, (this.store.readByte(1301) | 128) & 255);
  }
  /**
   * 写入比赛时间到 ram_0468/0469。
   */
  setTimer(minutes, seconds) {
    this.store.writeByte(1128, Math.max(0, Math.min(255, minutes)) & 255);
    this.store.writeByte(1129, Math.max(0, Math.min(59, seconds)) & 255);
  }
  /**
   * 写入双方比分。
   */
  setScore(home, away) {
    this.store.writeByte(1102, Math.max(0, Math.min(255, home)) & 255);
    this.store.writeByte(1104, Math.max(0, Math.min(255, away)) & 255);
  }
  /**
   * 数字 → HUD tile 索引（简化为 '0' + digit）。
   * 真实实现应查 CharMap.toTile()。
   */
  toTileDigit(d) {
    return 16 + (d & 15);
  }
  /**
   * 体力条绘制：按体力比例（0..255）映射 0..16 tile。
   * 当前 stub：只更新 ram_0620+slot；NT 缓冲留空（待 V0.5 真实实现）。
   */
  drawStaminaBar(slot, stamina) {
    if (slot < 0 || slot >= 22) return;
    this.store.writeByte(1568 + slot, stamina & 255);
  }
  /** 查询当前时间 */
  getTimer() {
    return {
      minutes: this.store.readByte(1128) & 255,
      seconds: this.store.readByte(1129) & 255
    };
  }
  /** 查询当前比分 */
  getScore() {
    return {
      home: this.store.readByte(1102) & 255,
      away: this.store.readByte(1104) & 255
    };
  }
};

