  { mask: 17, chLow: 0, chHigh: 4, group: 3 },
  // SQ1
  { mask: 34, chLow: 1, chHigh: 5, group: 2 },
  // SQ2
  { mask: 68, chLow: 2, chHigh: 6, group: 1 },
  // TRI
  { mask: 136, chLow: 3, chHigh: 7, group: 0 }
